    public static string Get(string localUrl) => Resolve(localUrl).Full;

    public static string GetShort(string localUrl) => Resolve(localUrl).Short;

    public static IEnumerable<string> All => Sources.Select(source => source.Full);

    private static Credit Resolve(string localUrl)
    {
        if (!ImageSources.TryGetValue(localUrl, out int sourceIndex))
        {
            throw new ArgumentException("Unknown bundled seed image URL.", nameof(localUrl));
        }

        return Sources[sourceIndex];
    }

    private sealed record Credit(string Full, string Short);
